Rewrite the following GNU C++11 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include<cstdio>
#include<cstring>
#include<iostream>
#include<stdlib.h>
#include<ctime>
#include<string>
#include<cmath>
#include<algorithm>
#include<complex>
#include<vector>
#include<set>
#include<map>
#include<queue>
#define pb push_back
#define mp make_pair
#define fi first
#define se second
#define LL long long
#define FOR(i,a,b) for (int i=a;i<=b;++i)
#define FORD(i,a,b) for (int i=a;i>=b;--i)
using namespace std;
typedef pair<int,int> pa;
void getint(int &v){
    char ch,fu=0;
    for(ch='*'; (ch<'0'||ch>'9')&&ch!='-'; ch=getchar());
    if(ch=='-') fu=1, ch=getchar();
    for(v=0; ch>='0'&&ch<='9'; ch=getchar()) v=v*10+ch-'0';
    if(fu) v=-v;
}
LL f[30][300010],ans,fac[300010],inv[300010];
int N,n,k,MO,s,p[1000010],a[55],S[1000010];
LL pw(LL x,int y){
	LL t=1;
	for (;y;y>>=1){
		if (y&1) t=t*x%MO;
		x=x*x%MO;
	}
	return t;
}
LL P(int x,int y){
	return fac[x]*inv[x-y]%MO;
}
int main(){
	scanf("%d%d%d",&n,&k,&MO);
	if (n&1) return cout<<pw(k,n)<<endl,0;
	fac[0]=1;
	FOR(i,1,n) fac[i]=fac[i-1]*i%MO;
	inv[n]=pw(fac[n],MO-2);
	FORD(i,n-1,0) inv[i]=inv[i+1]*(i+1)%MO;
	int t=n;
	FOR(i,0,20){
		if (t&1) a[s++]=1<<i;
		t>>=1;
	}
	N=1<<s;
	FOR(i,0,N-1)
		FOR(j,0,s-1)
			if ((i>>j)&1) S[i]+=a[j];
	FOR(i,0,N-1){
		int t=-1;
		FOR(j,0,20)
			if ((i>>j)&1) t=j;
		p[i]=(1<<(t+1))+i;
	}
	f[0][0]=1;
	FOR(i,0,k-1)
		FOR(j,0,N-1)
			if (f[i][j]){
				for (int k=p[j];k<N;k=(k+1)|j)
					(f[i+1][k]+=f[i][j]*inv[S[k^j]])%=MO;
			}
	FOR(i,0,k) (ans+=f[i][N-1]*P(k,i))%=MO;
	ans=ans*fac[n]%MO;
	ans=(pw(k,n)-ans+MO)%MO;
	cout<<ans<<endl;
	return 0;
}

